import sqlite3
import pandas as pd
import numpy as np
#making a DB
connection = sqlite3.connect('statystyki_pkmn.db')
cursor = connection.cursor()
###no need to run this file ever, its just backup for making dbs and whatnot:)
##limits the db to gen 3 or lower and fetches the names 
def names_pkmn():
    cursor.execute("SELECT Name FROM gen1 WHERE ID < 387") ### do we rlly need that rn? no ale spoko mniejsza baza czy cos
    names = cursor.fetchall()
    lista_imion = []
    for lista in names: ### 
        for krotka in lista:
            lista_imion.append(krotka)
    return lista_imion

def names_moves():
    cursor.execute('SELECT "Name   " FROM moves')
    moves_list_tmp = cursor.fetchall()
    moves_list = []
    for lista in moves_list_tmp:
        for krotka in moves_list_tmp:
            moves_list.append(krotka[0])
    return moves_list

def make_db():
    #making a DB
    df = pd.read_csv("C:/Users/Kacper/Desktop/programowanie/pkmncalc/Pokemon.csv")
    bf = pd.read_csv("C:/Users/Kacper/Desktop/programowanie/pkmncalc/moves.csv")
    connection = sqlite3.connect("statystyki_pkmn.db")
    df.to_sql('gen1',connection,if_exists='replace')
    bf.to_sql('moves',connection,if_exists='replace')
    connection = sqlite3.connect('statystyki_pkmn.db')
    cursor = connection.cursor()
    connection.close()





